'use strict';
(()=>{const D=window.GameData,K=window.CharacterData;
 const scenarios={focus:K.expeditionBattles[0],swarm:K.expeditionBattles[3],line:K.expeditionElite,boss:K.expeditionBoss};
 const names={base:'기초 덱',chain:'추격 보강',cover:'엄호 보강',movement:'기믹 이동 보강',trait_pursuit:'추격 특성 2단계',trait_escort:'호위 특성 2단계',trait_resonance:'공명 특성 2단계'},swaps={base:[],chain:[['serin_cut','serin_chain'],['serin_dash','serin_chain']],cover:[['serin_cut','serin_cover'],['serin_dash','serin_cover']],movement:[['serin_cut','boss_rescue'],['taunt','boss_retreat']],trait_pursuit:[['heal','serin_chain']],trait_escort:[['heal','serin_cover'],['shot','boss_rescue']],trait_resonance:[['taunt','boss_retreat']]};
 function deck(build){if(!swaps[build])throw Error('편성을 선택하세요.');const {pool,ids}=K.templatePool(K.starter),cards=ids.map((id,i)=>({...pool.find(c=>c.id===id),id:'condition:'+i}));for(const [old,key]of swaps[build]){const i=cards.findIndex(c=>c.key===old);cards[i]={id:cards[i].id,key,source:'reward',characterId:K.owner(key).id,upgraded:false};}const error=D.validateDeck(cards.map(c=>c.id),cards);if(error)throw Error(error);return cards;}
 function create(scenario,build,policy,ratio,seed,operation='traits'){if(!['traits','previous'].includes(operation)||!scenarios[scenario]||!['attack','protect'].includes(policy)||![1,.45,.25].includes(ratio)||!Number.isInteger(seed)||seed<0||seed>4294967295)throw Error('비교 조건을 확인하세요.');return new window.CharacterBattle({seed,levels:[1,1,1,1],hp:D.roles.map((_,i)=>D.maxHP(i,1)*ratio),stances:[0,1,0,0],depth:scenario==='swarm'?2:scenario==='line'?4:scenario==='boss'?5:0,elite:scenario==='line',encounter:scenarios[scenario],timing:'mixed',control:'auto',autoPolicy:policy,autoTraitVersion:operation==='previous'?0:1,cards:deck(build)});}
 function summarize(b,config){return {...config,operation:b.s.autoTraitVersion===1?'traits':'previous',win:b.s.winner===0,time:+b.s.t.toFixed(2),hp:+b.alive(0).reduce((n,a)=>n+a.hp,0).toFixed(2),healed:+b.s.stats.healed[0].toFixed(2),covered:+b.s.stats.covered.toFixed(2),blocked:b.s.stats.blocked[0],chain:b.s.stats.chainHits,signature:b.s.stats.signatureHits,moves:(b.s.mechanic?.stats.rescued||0)+(b.s.mechanic?.stats.repositioned||0),endReason:b.s.endReason||null,decisions:JSON.parse(JSON.stringify(b.s.autoDecisions)),traits:JSON.parse(JSON.stringify(b.s.traits)),uses:JSON.parse(JSON.stringify(b.s.stats.cards[0]))};}
 window.AutoLab={scenarios,names,swaps,deck,create,summarize};})();
